import{useEffect,useState}from"react";import{CheckCircle2,UserRound,CarFront,XCircle}from"lucide-react";import{getVendorRentalBookings,getVehicles,getDrivers,assignRental,updateRentalBookingStatus}from"../../api/rentalApi";
export default function RentalBookings(){const[data,setData]=useState([]),[vehicles,setVehicles]=useState([]),[drivers,setDrivers]=useState([]),[sel,setSel]=useState({}),[msg,setMsg]=useState("");const load=()=>Promise.all([getVendorRentalBookings(),getVehicles(),getDrivers()]).then(([a,b,c])=>{setData(a.data?.data||[]);setVehicles(b.data?.data||[]);setDrivers(c.data?.data||[])}).catch(e=>setMsg(e.response?.data?.message||"Could not load rental bookings"));useEffect(() => { load(); }, []);const act=async(fn)=>{try{await fn();setMsg("Updated");load()}catch(e){setMsg(e.response?.data?.message||"Update failed")}};return <div className="page-shell vendor-bg"><p className="eyebrow">RENTAL OPERATIONS</p><h1 className="page-title">Rental bookings</h1><p className="mt-2 text-sm text-slate-500">Confirm requests, assign compliant vehicles/drivers and monitor trips.</p>{msg&&<div className="mt-5 rounded-xl bg-slate-900 p-3 text-sm font-semibold text-white">{msg}</div>}<div className="mt-6 grid gap-4">{data.map(b=><div className="card p-5" key={b.id}><div className="flex flex-col gap-5 lg:flex-row lg:justify-between"><div className="min-w-0"><div className="flex flex-wrap gap-2"><span className="status-pill bg-slate-100">{b.status}</span><span className="status-pill bg-indigo-50 text-indigo-700">{b.journeyType}</span></div><h2 className="mt-2 text-xl font-black">{b.fromCity} → {b.toCity}</h2><p className="mt-1 text-sm text-slate-500">{b.travelDate} · {b.pickupTime} · {b.passengerCount} passengers</p><p className="mt-2 text-sm"><b>Pickup:</b> {b.pickupAddress}</p><p className="text-sm"><b>Drop:</b> {b.dropAddress}</p><p className="mt-2 text-xs text-slate-400">Estimate ₹{Number(b.estimatedFare||0).toLocaleString("en-IN")} · {b.bookingNumber}</p></div><div className="w-full max-w-md"><div className="grid gap-2 sm:grid-cols-2"><label><span className="label">Vehicle</span><select className="input" value={sel[b.id]?.vehicle||b.vehicleId||""} onChange={e=>setSel({...sel,[b.id]:{...sel[b.id],vehicle:e.target.value}})}><option value="">Select</option>{vehicles.filter(v=>v.status==="AVAILABLE"||v.id===b.vehicleId).map(v=><option key={v.id} value={v.id}>{v.registrationNumber} · {v.vehicleType}</option>)}</select></label><label><span className="label">Driver</span><select className="input" value={sel[b.id]?.driver||b.driverId||""} onChange={e=>setSel({...sel,[b.id]:{...sel[b.id],driver:e.target.value}})}><option value="">Select</option>{drivers.filter(d=>d.status==="ACTIVE").map(d=><option key={d.id} value={d.id}>{d.name} · {d.licenseNumber}</option>)}</select></label></div><div className="mt-3 flex flex-wrap gap-2"><button className="btn-primary" disabled={!sel[b.id]?.vehicle||!sel[b.id]?.driver} onClick={()=>act(()=>assignRental(b.id,sel[b.id].vehicle,sel[b.id].driver))}><CarFront size={15}/> Assign</button>{b.status==="REQUESTED"&&<button className="btn-secondary" onClick={()=>act(()=>updateRentalBookingStatus(b.id,{status:"VENDOR_CONFIRMED",note:"Vendor confirmed booking"}))}><CheckCircle2 size={15}/> Confirm</button>}{b.status==="REQUESTED"&&<button className="btn-secondary text-red-600" onClick={()=>act(()=>updateRentalBookingStatus(b.id,{status:"REJECTED",note:"Vehicle/driver unavailable"}))}><XCircle size={15}/> Reject</button>}</div></div></div></div>)}{!data.length&&<div className="card p-10 text-center text-slate-400">No rental requests.</div>}</div></div>}
